('psoas', 'Estiramiento de psoas', 'ficha', $j${"nombre":"Estiramiento de psoas","zona":"Movilidad","para_que":"Estira la parte delantera de la cadera (psoas) para que la pelvis quede neutra; contrarresta estar sentado.","patron":"estiramiento_cadera","musculos":{"principales":["psoas"],"secundarios":["gluteo_mayor"]},"posicion":"rodilla_en_suelo","tipo":"isometrico","lados":"por_lado","material":[],"nivel":1,"regresion":null,"progresion":null,"sustitutos":[],"carga":{"lumbar":0,"rodilla":1,"hombro":0,"muneca":0,"cuello":0},"evitar_si":"Si duele la rodilla de apoyo, pon una toalla doblada debajo.","usos":["movilidad","calentar","recuperar"],"dosis":{"secs":30,"rango":[20,60],"tempo_s":null},"apuntes":[]}$j$::jsonb, $j${"revisado":false,"info":"30 s cada pierna · entras en la postura y te quedas quieto","claves":["Las piernas NO se mueven: rodilla de atrás y pie de delante quietos","Primero aprieta el culo de la pierna de atrás y mete el coxis","Después lleva la cadera unos centímetros adelante, con el tronco recto","Lo notas en la parte delantera de la cadera de la pierna de atrás"],"fases":[{"texto":"Postura: rodilla de atrás en el suelo, tronco recto","segundos":2.4,"tono":null},{"texto":"Paso 1 · Aprieta fuerte el culo y mete el coxis hacia abajo","segundos":2.4,"tono":null},{"texto":"Paso 2 · Sin soltar el culo, lleva la cadera adelante unos cm","segundos":4.4,"tono":null}],"video":"estiramiento psoas rodilla en el suelo fisioterapeuta"}$j$::jsonb, $j${"revisado":false,"hold":true,"marks":{"gl":{"at":["p"],"off":[-8,3],"lab":[38,20]},"ab":{"at":["c"],"off":[8,0]}},"stretch":{"segs":[["p","k1"]],"lab":[34,62]},"poses":[{"h":[95,14],"s":[95,27],"p":[95,62],"k1":[85,98],"a1":[55,100],"k2":[128,70],"a2":[128,100],"e1":[86,44],"w1":[93,60],"e2":[88,44],"w2":[95,60]},{"h":[96,14],"s":[96,27],"p":[97,63],"k1":[85,98],"a1":[55,100],"k2":[130,70],"a2":[128,100],"e1":[87,44],"w1":[95,60],"e2":[89,44],"w2":[97,60]},{"h":[106,15],"s":[106,28],"p":[108,64],"k1":[85,98],"a1":[55,100],"k2":[139,73],"a2":[128,100],"e1":[97,45],"w1":[105,61],"e2":[99,45],"w2":[107,61]}],"phases":[{"pose":0,"move":1,"hold":1.4,"cap":"Postura: rodilla de atrás en el suelo, tronco recto"},{"pose":1,"move":0.6,"hold":1.8,"cap":"Paso 1 · Aprieta fuerte el culo y mete el coxis hacia abajo","sq":["gl"],"arrow":[74,42,80,60]},{"pose":2,"move":1.8,"hold":2.6,"cap":"Paso 2 · Sin soltar el culo, lleva la cadera adelante unos cm","sq":["gl"],"arrow":[112,38,136,38],"stretch":true}]}$j$::jsonb, $j${"paso1":{"ok":true,"fecha":"2026-11-14","apuntes":[]}}$j$::jsonb, 'rutina.json'),
('puente', 'Puente de glúteo', 'ficha', $j${"nombre":"Puente de glúteo","zona":"Glúteo","para_que":"Activa el glúteo y enseña a subir la cadera sin arquear la lumbar.","patron":"puente_cadera","musculos":{"principales":["gluteo_mayor"],"secundarios":["isquios","transverso"]},"posicion":"boca_arriba","tipo":"reps","lados":"bilateral","material":[],"nivel":1,"regresion":null,"progresion":"puente_banda","sustitutos":["puente_banda"],"carga":{"lumbar":1,"rodilla":0,"hombro":0,"muneca":0,"cuello":0},"evitar_si":"Si notas la lumbar más que el culo, sube menos.","usos":["core","fuerza","calentar"],"dosis":{"reps":15,"rango":[10,20],"tempo_s":4},"apuntes":[]}$j$::jsonb, $j${"revisado":false,"info":"15 reps · 4 s cada una · las dos piernas a la vez","claves":["Boca arriba, rodillas dobladas y pies apoyados","Antes de subir, aplana la zona lumbar contra el suelo","Sube la cadera apretando el culo, empujando con los talones","Arriba: hombros, cadera y rodillas en línea, sin arquear"],"fases":[{"texto":"Sube en 1 s apretando el culo y aguanta 1 s arriba","segundos":2,"tono":"up"},{"texto":"Baja despacio (2 s) con el ombligo dentro","segundos":2,"tono":"down"}],"video":"puente de glúteo técnica correcta fisioterapeuta"}$j$::jsonb, $j${"revisado":false,"rep":4,"unit":"Repetición","marks":{"gl":{"at":["p"],"off":[-2,5],"lab":[135,28]},"ab":{"at":["c"],"off":[0,-7],"lab":[40,62]}},"poses":[{"h":[26,94],"s":[40,97],"p":[90,98],"k1":[120,74],"a1":[135,100],"k2":[118,75],"a2":[133,100],"e1":[60,100],"w1":[78,100],"e2":[60,100],"w2":[78,100]},{"h":[28,93],"s":[46,95],"p":[95,72],"k1":[126,67],"a1":[135,100],"k2":[124,68],"a2":[133,100],"e1":[64,100],"w1":[82,100],"e2":[64,100],"w2":[82,100]}],"phases":[{"pose":1,"move":1,"hold":1,"tone":"up","cap":"Sube en 1 s apretando el culo y aguanta 1 s arriba","sq":["gl"],"arrow":[108,96,108,70]},{"pose":0,"move":1.5,"hold":0.5,"tone":"down","cap":"Baja despacio (2 s) con el ombligo dentro","sq":["ab"]}]}$j$::jsonb, $j${"paso1":{"ok":true,"fecha":"2026-11-14","apuntes":[]}}$j$::jsonb, 'rutina.json'),
('deadbug', 'Dead bug', 'ficha', $j${"nombre":"Dead bug","zona":"Core","para_que":"Abdomen profundo: mover brazos y piernas sin que se despegue la lumbar.","patron":"anti_extension","musculos":{"principales":["recto_abdominal","transverso"],"secundarios":["oblicuos","psoas"]},"posicion":"boca_arriba","tipo":"reps","lados":"alterno","material":[],"nivel":1,"regresion":null,"progresion":"hollow_k","sustitutos":["hollow_k"],"carga":{"lumbar":0,"rodilla":0,"hombro":0,"muneca":0,"cuello":0},"evitar_si":"","usos":["core","calentar"],"dosis":{"reps":16,"rango":[8,20],"tempo_s":4},"apuntes":["Comprobar en 3D que la espalda apoya en el suelo (la comprobación 2D no sirve para los tumbados)"]}$j$::jsonb, $j${"revisado":false,"info":"8 por lado (16 en total) · 4 s cada una · alternando","claves":["Boca arriba, brazos al techo y rodillas dobladas a 90° en el aire","Estira a la vez un brazo atrás y la pierna contraria adelante","La zona lumbar no se despega del suelo en ningún momento","Suelta el aire al estirar; si se despega la espalda, estira menos"],"fases":[{"texto":"Estira un brazo atrás y la pierna contraria adelante (2 s)","segundos":2,"tono":"up"},{"texto":"Vuelve al centro (2 s), lumbar pegada al suelo","segundos":2,"tono":"down"},{"texto":"Ahora el otro brazo y la otra pierna (2 s)","segundos":2,"tono":"up"},{"texto":"Vuelve al centro (2 s)","segundos":2,"tono":"down"}],"video":"dead bug ejercicio técnica correcta"}$j$::jsonb, $j${"revisado":false,"rep":4,"unit":"Repetición","marks":{"ab":{"at":["c"],"off":[0,-7],"lab":[80,18]}},"poses":[{"h":[30,92],"s":[44,95],"p":[95,96],"k1":[95,64],"a1":[125,64],"k2":[97,64],"a2":[127,64],"e1":[44,77],"w1":[44,59],"e2":[46,77],"w2":[46,59]},{"h":[30,92],"s":[44,95],"p":[95,96],"k1":[95,64],"a1":[125,64],"k2":[127,80],"a2":[158,90],"e1":[27,86],"w1":[10,92],"e2":[46,77],"w2":[46,59]},{"h":[30,92],"s":[44,95],"p":[95,96],"k1":[127,80],"a1":[158,90],"k2":[97,64],"a2":[127,64],"e1":[44,77],"w1":[44,59],"e2":[29,86],"w2":[12,92]}],"phases":[{"pose":1,"move":1.5,"hold":0.5,"tone":"up","cap":"Estira un brazo atrás y la pierna contraria adelante (2 s)","sq":["ab"],"arrow":[150,62,165,80]},{"pose":0,"move":1.5,"hold":0.5,"tone":"down","cap":"Vuelve al centro (2 s), lumbar pegada al suelo","sq":["ab"]},{"pose":2,"move":1.5,"hold":0.5,"tone":"up","cap":"Ahora el otro brazo y la otra pierna (2 s)","sq":["ab"],"arrow":[150,62,165,80]},{"pose":0,"move":1.5,"hold":0.5,"tone":"down","cap":"Vuelve al centro (2 s)","sq":["ab"]}]}$j$::jsonb, $j${"paso1":{"ok":true,"fecha":"2026-11-14","apuntes":["Comprobar en 3D que la espalda apoya en el suelo (la comprobación 2D no sirve para los tumbados)"]}}$j$::jsonb, 'rutina.json'),
('plancha', 'Plancha con retroversión', 'ficha', $j${"nombre":"Plancha con retroversión","zona":"Core","para_que":"Aguantar el tronco recto contra la gravedad (anti-extensión) con la pelvis metida.","patron":"anti_extension","musculos":{"principales":["recto_abdominal","transverso"],"secundarios":["gluteo_mayor","deltoides_anterior","serrato"]},"posicion":"boca_abajo","tipo":"isometrico","lados":"bilateral","material":[],"nivel":1,"regresion":null,"progresion":null,"sustitutos":["deadbug","hollow_k"],"carga":{"lumbar":1,"rodilla":0,"hombro":1,"muneca":0,"cuello":0},"evitar_si":"Si notas la lumbar, cambia a dead bug.","usos":["core"],"dosis":{"secs":30,"rango":[15,60],"tempo_s":null},"apuntes":["La primera fase enseña el error («Así NO»): en el paso 2 decidir si se queda"]}$j$::jsonb, $j${"revisado":false,"info":"30 s quieto · todo el cuerpo a la vez","claves":["Apoyado en antebrazos y puntas de los pies","Error típico: la zona lumbar se hunde","Aprieta el culo y mete el ombligo: la cadera se alinea","Mantén el cuerpo recto como una tabla"],"fases":[{"texto":"Así NO: la lumbar se hunde","segundos":2.4,"tono":null},{"texto":"Aprieta el culo y mete el ombligo: el cuerpo queda recto","segundos":3.6,"tono":null}],"video":"plancha abdominal retroversión pélvica técnica"}$j$::jsonb, $j${"revisado":false,"hold":true,"marks":{"gl":{"at":["p"],"off":[2,-7],"lab":[135,40]},"ab":{"at":["c"],"off":[0,7],"lab":[36,40]}},"poses":[{"h":[28,68],"s":[42,73],"c":[71,86],"p":[100,83],"k1":[128,92],"a1":[156,95],"k2":[129,93],"a2":[157,95],"e1":[42,100],"w1":[22,100],"e2":[44,100],"w2":[24,100]},{"h":[28,68],"s":[42,73],"c":[71,73],"p":[100,74],"k1":[128,88],"a1":[156,95],"k2":[129,89],"a2":[157,95],"e1":[42,100],"w1":[22,100],"e2":[44,100],"w2":[24,100]}],"phases":[{"pose":0,"move":1,"hold":1.4,"cap":"Así NO: la lumbar se hunde"},{"pose":1,"move":1,"hold":2.6,"cap":"Aprieta el culo y mete el ombligo: el cuerpo queda recto","sq":["gl","ab"],"arrow":[88,100,88,84]}]}$j$::jsonb, $j${"paso1":{"ok":true,"fecha":"2026-11-14","apuntes":["La primera fase enseña el error («Así NO»): en el paso 2 decidir si se queda"]}}$j$::jsonb, 'rutina.json'),
('gato', 'Gato-camello', 'ficha', $j${"nombre":"Gato-camello","zona":"Movilidad","para_que":"Mueve la columna entera, vértebra a vértebra, al ritmo de la respiración.","patron":"movilidad_columna","musculos":{"principales":["erectores","recto_abdominal"],"secundarios":[]},"posicion":"cuadrupedia","tipo":"reps","lados":"bilateral","material":[],"nivel":1,"regresion":null,"progresion":null,"sustitutos":[],"carga":{"lumbar":0,"rodilla":1,"hombro":0,"muneca":1,"cuello":0},"evitar_si":"Si duelen las muñecas, apóyate en los puños.","usos":["movilidad","calentar","recuperar"],"dosis":{"reps":6,"rango":[5,10],"tempo_s":7},"apuntes":[]}$j$::jsonb, $j${"revisado":false,"info":"6 respiraciones lentas · 7 s cada una","claves":["A cuatro patas: manos bajo los hombros, rodillas bajo la cadera","Coge aire: deja caer la barriga y mira al frente","Suelta el aire: redondea la espalda hacia arriba y mira al ombligo","Movimiento lento, que empiece en la pelvis"],"fases":[{"texto":"Coge aire: deja caer la barriga y mira al frente","segundos":3.5,"tono":"down"},{"texto":"Suelta el aire: redondea la espalda y mete el ombligo","segundos":3.5,"tono":"up"}],"video":"gato camello ejercicio fisioterapia"}$j$::jsonb, $j${"revisado":false,"rep":7,"unit":"Respiración","marks":{"ab":{"at":["c"],"off":[0,8],"lab":[135,22]}},"poses":[{"h":[42,52],"s":[55,62],"c":[85,77],"p":[115,62],"k1":[115,100],"a1":[150,100],"k2":[117,100],"a2":[152,100],"e1":[55,81],"w1":[55,100],"e2":[57,81],"w2":[57,100]},{"h":[46,79],"s":[55,62],"c":[85,40],"p":[115,62],"k1":[115,100],"a1":[150,100],"k2":[117,100],"a2":[152,100],"e1":[55,81],"w1":[55,100],"e2":[57,81],"w2":[57,100]}],"phases":[{"pose":0,"move":3,"hold":0.5,"tone":"down","cap":"Coge aire: deja caer la barriga y mira al frente","arrow":[85,62,85,78]},{"pose":1,"move":3,"hold":0.5,"tone":"up","cap":"Suelta el aire: redondea la espalda y mete el ombligo","sq":["ab"],"arrow":[85,50,85,32]}]}$j$::jsonb, $j${"paso1":{"ok":true,"fecha":"2026-11-14","apuntes":[]}}$j$::jsonb, 'rutina.json'),
('crunch_inv', 'Crunch inverso', 'ficha', $j${"nombre":"Crunch inverso","zona":"Core","para_que":"Abdomen con flexión de tronco desde abajo: sube la pelvis, no las piernas.","patron":"flexion_tronco","musculos":{"principales":["recto_abdominal"],"secundarios":["transverso","oblicuos"]},"posicion":"boca_arriba","tipo":"reps","lados":"bilateral","material":[],"nivel":2,"regresion":null,"progresion":null,"sustitutos":["hollow_k","deadbug"],"carga":{"lumbar":1,"rodilla":0,"hombro":0,"muneca":0,"cuello":0},"evitar_si":"Si tiras con las piernas o con impulso, haz menos.","usos":["core","fuerza"],"dosis":{"reps":15,"rango":[8,20],"tempo_s":5},"apuntes":["La clave «Las 2–3 últimas tienen que costar» es de dosis, no de técnica"]}$j$::jsonb, $j${"revisado":false,"info":null,"claves":["Boca arriba, rodillas dobladas a 90° en el aire, brazos en el suelo","Lleva las rodillas al pecho despegando solo el coxis","Sin impulso: sube con el abdomen, no con las piernas","Las 2–3 últimas tienen que costar: si no, sube de nivel"],"fases":[{"texto":"Sube: rodillas al pecho, despega el coxis y aprieta 1 s","segundos":2,"tono":"up"},{"texto":"Baja muy despacio (3 s) sin arquear la lumbar","segundos":3,"tono":"down"}],"video":"crunch inverso técnica correcta retroversión"}$j$::jsonb, $j${"revisado":false,"rep":5,"unit":"Repetición","marks":{"ab":{"at":["c"],"off":[0,-7],"lab":[40,62]}},"poses":[{"h":[26,94],"s":[40,97],"c":[65,98],"p":[90,97],"k1":[92,64],"a1":[122,66],"k2":[94,65],"a2":[124,67],"e1":[58,100],"w1":[76,100],"e2":[60,100],"w2":[78,100]},{"h":[26,94],"s":[40,97],"c":[62,95],"p":[82,88],"k1":[66,60],"a1":[94,50],"k2":[68,61],"a2":[96,51],"e1":[58,100],"w1":[76,100],"e2":[60,100],"w2":[78,100]}],"phases":[{"pose":1,"move":1.5,"hold":0.5,"tone":"up","sq":["ab"],"arrow":[116,84,96,62],"cap":"Sube: rodillas al pecho, despega el coxis y aprieta 1 s"},{"pose":0,"move":2.5,"hold":0.5,"tone":"down","sq":["ab"],"cap":"Baja muy despacio (3 s) sin arquear la lumbar"}]}$j$::jsonb, $j${"paso1":{"ok":true,"fecha":"2026-11-14","apuntes":["La clave «Las 2–3 últimas tienen que costar» es de dosis, no de técnica"]}}$j$::jsonb, 'rutina.json'),
('hollow_k', 'Hollow hold', 'ficha', $j${"nombre":"Hollow hold","zona":"Core","para_que":"Hollow fácil: lumbar pegada con hombros y rodillas en el aire.","patron":"anti_extension","musculos":{"principales":["recto_abdominal","transverso"],"secundarios":["psoas"]},"posicion":"boca_arriba","tipo":"isometrico","lados":"bilateral","material":[],"nivel":2,"regresion":"deadbug","progresion":"hollow_kb","sustitutos":["plancha"],"carga":{"lumbar":1,"rodilla":0,"hombro":0,"muneca":0,"cuello":1},"evitar_si":"Si se despega la lumbar o tira el cuello, vuelve al dead bug.","usos":["core"],"dosis":{"secs":20,"rango":[15,40],"tempo_s":null},"apuntes":["Nombre en inglés y casi igual a los otros dos hollow: el nombre no dice qué cambia (rodillas dobladas)"]}$j$::jsonb, $j${"revisado":false,"info":null,"claves":["Boca arriba: pega la lumbar al suelo antes de nada","Despega los hombros y lleva las rodillas encima de la cadera","Brazos estirados hacia las rodillas, ombligo dentro","Si la lumbar se despega, acerca más las rodillas"],"fases":[{"texto":"Boca arriba: pega la lumbar al suelo","segundos":2,"tono":null},{"texto":"Despega hombros y rodillas; la lumbar NO se despega","segundos":4.2,"tono":null}],"video":"hollow hold rodillas dobladas principiante"}$j$::jsonb, $j${"revisado":false,"hold":true,"marks":{"ab":{"at":["c"],"off":[0,-7],"lab":[70,40]}},"poses":[{"h":[26,94],"s":[40,97],"p":[90,98],"k1":[120,74],"a1":[135,100],"k2":[118,75],"a2":[133,100],"e1":[60,100],"w1":[78,100],"e2":[62,100],"w2":[80,100]},{"h":[30,84],"s":[44,91],"c":[70,97],"p":[95,97],"k1":[96,65],"a1":[126,67],"k2":[98,66],"a2":[128,68],"e1":[60,84],"w1":[77,79],"e2":[62,84],"w2":[79,79]}],"phases":[{"pose":0,"move":1,"hold":1,"sq":["ab"],"cap":"Boca arriba: pega la lumbar al suelo"},{"pose":1,"move":1.2,"hold":3,"sq":["ab"],"arrow":[112,98,112,74],"cap":"Despega hombros y rodillas; la lumbar NO se despega"}]}$j$::jsonb, $j${"paso1":{"ok":true,"fecha":"2026-11-14","apuntes":["Nombre en inglés y casi igual a lo