('ext_db', 'Extensión de tríceps tumbado', 'ficha', $j${"nombre":"Extensión de tríceps tumbado","zona":"Brazos","para_que":"Tríceps tumbado con mancuernas (codos al techo).","patron":"extension_codo","musculos":{"principales":["triceps"],"secundarios":[]},"posicion":"boca_arriba","tipo":"reps","lados":"bilateral","material":["mancuernas"],"nivel":1,"regresion":null,"progresion":null,"sustitutos":["fondos","flex_cerr"],"carga":{"lumbar":0,"rodilla":0,"hombro":0,"muneca":0,"cuello":0},"evitar_si":"","usos":["fuerza"],"dosis":{"reps":12,"rango":[8,15],"tempo_s":4,"kg":[6,8]},"apuntes":[]}$j$::jsonb, $j${"revisado":false,"info":null,"claves":["Tumbado en el suelo, rodillas dobladas, lumbar apoyada","Brazos estirados hacia el techo con las mancuernas","Dobla solo los codos: las mancuernas bajan junto a la cabeza","Los codos apuntan al techo y no se abren"],"fases":[{"texto":"Dobla los codos: mancuernas junto a la cabeza (2 s)","segundos":2,"tono":"down"},{"texto":"Estira los brazos; los codos apuntan al techo","segundos":2,"tono":"up"}],"video":"extensión tríceps tumbado mancuernas suelo"}$j$::jsonb, $j${"revisado":false,"rep":4,"unit":"Repetición","marks":{"tri":{"at":["s","e1"],"off":[5,0],"lab":[84,40]}},"equip":[{"t":"db","at":"w1"},{"t":"db","at":"w2"}],"poses":[{"h":[26,94],"s":[40,97],"p":[90,98],"k1":[120,74],"a1":[135,100],"k2":[118,75],"a2":[133,100],"e1":[42,78],"w1":[43,60],"e2":[44,78],"w2":[45,60]},{"h":[26,94],"s":[40,97],"p":[90,98],"k1":[120,74],"a1":[135,100],"k2":[118,75],"a2":[133,100],"e1":[42,78],"w1":[25,82],"e2":[44,78],"w2":[27,82]}],"phases":[{"pose":1,"move":1.5,"hold":0.5,"tone":"down","sq":["tri"],"cap":"Dobla los codos: mancuernas junto a la cabeza (2 s)"},{"pose":0,"move":1.5,"hold":0.5,"tone":"up","sq":["tri"],"arrow":[58,84,58,62],"cap":"Estira los brazos; los codos apuntan al techo"}]}$j$::jsonb, $j${"paso1":{"ok":true,"fecha":"2026-11-14","apuntes":[]}}$j$::jsonb, 'rutina.json'),
