('puente_banda', 'Puente de glúteo con banda', 'ficha', $j${"nombre":"Puente de glúteo con banda","zona":"Glúteo","para_que":"Puente con mini banda: glúteo mayor y también el medio (empujar las rodillas hacia fuera).","patron":"puente_cadera","musculos":{"principales":["gluteo_mayor","gluteo_medio"],"secundarios":["isquios","transverso"]},"posicion":"boca_arriba","tipo":"reps","lados":"bilateral","material":["banda"],"nivel":1,"regresion":"puente","progresion":"puente_abd","sustitutos":["puente"],"carga":{"lumbar":1,"rodilla":0,"hombro":0,"muneca":0,"cuello":0},"evitar_si":"Si notas la lumbar más que el culo, sube menos.","usos":["core","fuerza","calentar"],"dosis":{"reps":15,"rango":[10,20],"tempo_s":4},"apuntes":[]}$j$::jsonb, $j${"revisado":false,"info":"15 reps · 4 s cada una · las dos piernas a la vez","claves":["Banda por encima de las rodillas, pies a la anchura de la cadera","Antes de subir, aplana la zona lumbar contra el suelo","Sube apretando el culo y empujando las rodillas hacia fuera contra la banda","Arriba: hombros, cadera y rodillas en línea, sin arquear"],"fases":[{"texto":"Sube en 1 s apretando el culo y aguanta 1 s arriba","segundos":2,"tono":"up"},{"texto":"Baja despacio (2 s) con el ombligo dentro","segundos":2,"tono":"down"}],"video":"puente de glúteo con banda en las rodillas"}$j$::jsonb, $j${"revisado":false,"rep":4,"unit":"Repetición","marks":{"gl":{"at":["p"],"off":[-2,5],"lab":[135,28]},"ab":{"at":["c"],"off":[0,-7],"lab":[40,62]}},"equip":[{"t":"band","at":"k1","to":"k2","label":"BANDA"}],"poses":[{"h":[26,94],"s":[40,97],"p":[90,98],"k1":[120,74],"a1":[135,100],"k2":[118,75],"a2":[133,100],"e1":[60,100],"w1":[78,100],"e2":[60,100],"w2":[78,100]},{"h":[28,93],"s":[46,95],"p":[95,72],"k1":[126,67],"a1":[135,100],"k2":[124,68],"a2":[133,100],"e1":[64,100],"w1":[82,100],"e2":[64,100],"w2":[82,100]}],"phases":[{"pose":1,"move":1,"hold":1,"tone":"up","cap":"Sube en 1 s apretando el culo y aguanta 1 s arriba","sq":["gl"],"arrow":[108,96,108,70