('puente_abd', 'Puente con apertura de rodillas', 'ficha', $j${"nombre":"Puente con apertura de rodillas","zona":"Glúteo","para_que":"Puente mantenido abriendo las rodillas contra la banda: glúteo medio.","patron":"abduccion_cadera","musculos":{"principales":["gluteo_medio","gluteo_mayor"],"secundarios":["isquios"]},"posicion":"boca_arriba","tipo":"reps","lados":"bilateral","material":["banda"],"nivel":2,"regresion":"puente_banda","progresion":null,"sustitutos":["almeja"],"carga":{"lumbar":1,"rodilla":0,"hombro":0,"muneca":0,"cuello":0},"evitar_si":"Si notas la lumbar, baja un poco la cadera.","usos":["fuerza"],"dosis":{"reps":15,"rango":[10,20],"tempo_s":3},"apuntes":[]}$j$::jsonb, $j${"revisado":false,"info":null,"claves":["Banda por encima de las rodillas y cadera arriba en puente","Quédate arriba todo el rato, culo apretado","Abre las rodillas contra la banda y vuelve despacio","Si notas la lumbar, baja un poco la cadera"],"fases":[{"texto":"Abre las rodillas contra la banda","segundos":1.5,"tono":"up"},{"texto":"Cierra despacio sin bajar la cadera","segundos":1.5,"tono":"down"}],"video":"puente de glúteo abducción con banda"}$j$::jsonb, $j${"revisado":false,"rep":3,"unit":"Repetición","marks":{"glm":{"at":["p"],"off":[-2,5],"lab":[140,24],"text":"ABRE LAS RODILLAS"}},"equip":[{"t":"band","at":"k1","to":"k2","label":"BANDA"}],"poses":[{"h":[28,93],"s":[46,95],"p":[95,72],"k1":[126,67],"a1":[135,100],"k2":[124,68],"a2":[133,100],"e1":[64,100],"w1":[82,100],"e2":[64,100],"w2":[82,100]},{"h":[28,93],"s":[46,95],"p":[95,72],"k1":[126,74],"a1":[135,100],"k2":[121,58],"a2":[133,100],"e1":[64,100],"w1":[82,100],"e2":[64,100],"w2":[82,100]}],"phases":[{"pose":1,"move":1,"hold":0.5,"tone":"up","sq":["glm"],"arrow":[136,64,136,48],"cap":"Abre las rodillas contra la banda"},{"pose":0,"move":1,"hold":0.5,"tone":"down","cap":"Cierra despacio sin bajar la cadera"}]}$j$::jsonb, $j${"paso1":{"ok":true,"fecha":"2026-11-14","apuntes":[]}}$j$::jsonb, 'rutina.json'),
('paso_lateral', 'Paso lateral con banda', 'ficha', $j${"nombre":"Paso lateral con banda","zona":"Glúteo","para_que":"Pasos de lado con la banda: glúteo medio y estabilidad de rodilla.","patron":"desplazamiento_lateral","musculos":{"principales":["gluteo_medio"],"secundarios":["gluteo_mayor","cuadriceps"]},"posicion":"de_pie","tipo":"reps","lados":"por_lado","material":["banda"],"nivel":2,"regresion":null,"progresion":null,"sustitutos":["almeja","puente_abd"],"carga":{"lumbar":0,"rodilla":1,"hombro":0,"muneca":0,"cuello":0},"evitar_si":"Si se te van las rodillas hacia dentro, pasos más cortos.","usos":["fuerza","calentar"],"dosis":{"reps":10,"rango":[8,15],"tempo_s":2},"apuntes":[]}$j$::jsonb, $j${"revisado":false,"info":null,"claves":["Banda por encima de las rodillas, medio agachado","Pecho alto y culo atrás, sin arquear la lumbar","Da un paso de lado sin juntar del todo los pies","Las rodillas empujan hacia fuera todo el rato"],"fases":[{"texto":"Paso de lado, rodillas hacia fuera","segundos":1,"tono":"up"},{"texto":"Acerca el otro pie sin juntarlos del todo","segundos":1,"tono":"down"}],"video":"paso lateral con banda glúteo medio monster walk"}$j$::jsonb, $j${"revisado":false,"view":"frente","rep":2,"unit":"Paso","front":true,"marks":{"glm":{"at":["p"],"off":[0,4],"lab":[150,30],"text":"GLÚTEO DE LADO"}},"equip":[{"t":"band","at":"k1","to":"k2","label":"BANDA"}],"poses":[{"h":[90,26],"s":[90,38],"p":[90,68],"k1":[80,84],"a1":[80,100],"k2":[100,84],"a2":[100,100],"e1":[80,52],"w1":[84,64],"e2":[100,52],"w2":[96,64]},{"h":[86,26],"s":[86,38],"p":[86,68],"k1":[72,84],"a1":[66,100],"k2":[100,84],"a2":[100,100],"e1":[76,52],"w1":[80,64],"e2":[96,52],"w2":[92,64]}],"phases":[{"pose":1,"move":0.7,"hold":0.3,"tone":"up","sq":["glm"],"arrow":[60,92,44,92],"cap":"Paso de lado, rodillas hacia fuera"},{"pose":0,"move":0.7,"hold":0.3,"tone":"down","cap":"Acerca el otro pie sin juntarlos del todo"}]}$j$::jsonb, $j${"paso1":{"ok":true,"fecha":"2026-11-14","apuntes":[]}}$j$::j